    ["Too many keys. Keep {max} or fewer."] = "Příliš mnoho klíčů. Nech {max} nebo méně.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” není použitelný název klíče. Použij písmena, číslice a podtržítka.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” má v tomto formuláři vlastní nastavení. Použij je místo něj.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Pro délku odpovědi použij pole Nejdelší odpověď, ne “{name}”.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” nastavuje mod a zde ho nelze změnit.",
