    ["Choose one of the listed reply languages."] = "Vyberte jeden z uvedených jazyků odpovědí.",
    ["No speech was heard. Hold the talk key while you speak."] = "Nebyla zachycena žádná řeč. Drž hlasovou klávesu, dokud mluvíš.",
    ["Voice activation"] = "Hlasová aktivace",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Hlasová aktivace nemohla otevřít mikrofon. Zkontroluj vstupní zařízení ve Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Hlasový vstup se nepodařilo spojit s Convai. Podrž znovu hlasovou klávesu, nebo napiš.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Mluv bez držení klávesy. Když stojíš tváří k postavě nebo je poblíž společník, mod poslouchá a odpoví, když na asi sekundu zmlkneš.\n\nNikdy během vlastních scén hry, výběru dialogových možností ani když postava mluví. Z tvého PC nic neodchází, dokud se neozve řeč. Nejlépe fungují sluchátka, ale mikrofon Bluetooth sluchátek přepne na kvalitu hovoru, dokud tohle poslouchá.",
    ["Opening microphone…"] = "Otevírám mikrofon…",
    ["Speak now"] = "Mluv teď",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Model najdeš podle jména nebo záznamu v poli pro vyhledávání, například „rita wheeler“. Stačí i část slova.",
    ["Content packs"] = "Obsahové balíčky",
    ["Add-ons that change how the characters talk."] = "Doplňky, které mění, jak postavy mluví.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Obsahové balíčky přidávají pravidla za tvými. Tady je nelze upravovat: vypni balíček ve hře v Nastavení > Obsahové balíčky.",
    ["From the content pack {name}"] = "Z obsahového balíčku {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Obsahové balíčky, které mění tento prompt: {names}. Tvé vlastní změny zůstávají nad jejich, a Obnovit výchozí vrátí znění balíčku.",
    ["Memory in use"] = "Používaná paměť",
    ["Normal memory"] = "Běžná paměť",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Zapomenout vzpomínky smaže jen paměť zobrazenou zde. Ostatní paměť zůstane beze změny.",
    ["This clears the memory in use: {memory}."] = "Smaže používanou paměť: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Zrušeno.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Vyber klávesu nebo tlačítko ovladače.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Vyber klávesy a tlačítka ovladače pro mluvení hlasem nebo textem, skupinové chaty a Správce společníků. Fungují hned.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Vyber klávesy a tlačítka ovladače pro akce modu. Stiskni Nastavit a pak klávesu nebo tlačítko, které chceš. Esc nebo B zruší. Změna funguje hned a klávesy nastavené v Cyber Engine Tweaks dál fungují. Vybírej klávesy, které hra nepoužívá.",
    ["Controller {button}"] = "Ovladač: {button}",
    ["D-pad down"] = "Křížák dolů",
    ["D-pad left"] = "Křížák vlevo",
    ["D-pad right"] = "Křížák vpravo",
    ["D-pad up"] = "Křížák nahoru",
    ["Down arrow"] = "Šipka dolů",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Skupinový text",
    ["Group voice chat"] = "Skupinový hlas",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Podrž ji, aby ses hned mohl bavit se všemi postavami kolem tebe, a pusť pro odeslání. Když se na nikoho nedíváš, mluvíš s prvním členem party a dvěma dalšími členy.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Podrž ji, abys mohl mluvit s Johnnym, hlasem ve tvé hlavě, ať se díváš kamkoli, a pusť pro odeslání. Vyžaduje, aby byl Johnny v hlavě zapnutý v Nastavení.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Drž klávesu nebo tlačítko, dokud mluvíš, a pusť pro odeslání, stejně jako klávesa pro mluvení v Cyber Engine Tweaks. Když se na nikoho nedíváš, mluvíš s prvním členem party.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Klávesy",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Klávesy potřebují Codeware, který tahle hra nemá. Otevři Nápovědu, co chybí.",
    ["Key or button"] = "Klávesa/tlačítko",
    ["Left arrow"] = "Šipka vlevo",
    ["Menu"] = "Menu",
    ["No key was pressed, so nothing changed."] = "Nestiskla se žádná klávesa, takže se nic nezměnilo.",
    ["Not available"] = "Nedostupné",
    ["Not set"] = "Nenastaveno",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Stiskni ho a pak klávesu nebo tlačítko ovladače, které chceš. Esc nebo B zruší. Funguje hned.",
    ["Press it to open the Companion Manager while you play."] = "Stiskni pro otevření Správce společníků během hry.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Stiskni pro psaní postavě, před kterou stojíš. Když se na nikoho nedíváš, píšeš prvnímu členovi party.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Stiskni pro psaní Johnnymu, hlasu ve tvé hlavě, ať se díváš kamkoli. Vyžaduje, aby byl Johnny v hlavě zapnutý v Nastavení.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Stiskni pro psaní všem postavám kolem tebe najednou. Když se na nikoho nedíváš, píšeš prvnímu členovi party a dvěma dalším členům.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Stiskni klávesu nebo tlačítko ovladače pro {action}. Esc nebo B zruší.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Odeber klávesu nebo tlačítko, které jsi tady nastavil.",
    ["Right arrow"] = "Šipka vpravo",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Mezerník",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Mluvit textem",
    ["Talk by voice"] = "Mluvit hlasem",
    ["Talk to Johnny by text"] = "Mluvit s Johnnym textem",
    ["Talk to Johnny by voice"] = "Mluvit s Johnnym hlasem",
    ["That key is already used for another action."] = "Tahle klávesa už je použitá pro jinou akci.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Klávesy modu se nepodařilo načíst. Otevři Nápovědu, co je špatně.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Skripty modu se nenačetly, takže nejde nastavit žádná klávesa. Otevři Nápovědu, co je špatně.",
    ["Up arrow"] = "Šipka nahoru",
    ["View"] = "Zobrazení",
    ["{action} cleared."] = "{action} vymazáno.",
    ["{action} is set to {key}."] = "{action} je nastaveno na {key}.",
    ["{key} is already used for {other}. Choose another."] = "Klávesa {key} už je použita pro {other}. Vyber jinou.",
    ["10 minutes"] = "10 minut",
    ["2 minutes"] = "2 minuty",
    ["5 minutes"] = "5 minut",
    ["Cancel this meeting. She is not told."] = "Zrušit schůzku. Nedozví se o tom.",
    ["Car"] = "Autem",
    ["Choose how long she waits."] = "Vyber, jak dlouho bude čekat.",
    ["Choose how she arrives."] = "Vyber, jak přijede.",
    ["Choose one of the listed options."] = "Vyber jednu z nabízených možností.",
    ["Choose when she arrives."] = "Vyber, kdy přijede.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Společníci k tobě přijdou, když je pozveš: přijdou pěšky nebo přijedou autem, napíšou ti, počkají a zapamatují si, když nepřijdeš.\n\nVýchozí: vypnuto.",
    ["Fine. Call me when you know what you want."] = "Fajn. Ozvi se, až budeš vědět, co chceš.",
    ["How long she waits"] = "Jak dlouho bude čekat",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Jak dlouho na tebe bude čekat hned po příjezdu. Po časovaném příjezdu čeká tak dlouho, jak dlouhé zpoždění vybereš. Čekání se zastaví, když jsi v boji, ve scéně nebo v menu.",
    ["How she arrives"] = "Jak přijede",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Čekala jsem {minutes} minut na {place} a ty ses nikdy neukázal. Zapomeň na to.",
    ["I'm here at {place}. Where are you?"] = "Jsem tady na {place}. Kde jsi?",
    ["Immersive invitations"] = "Pohlcující pozvánky",
    ["In 10 minutes"] = "Za 10 minut",
    ["In 2 minutes"] = "Za 2 minuty",
    ["In 5 minutes"] = "Za 5 minut",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Pozvi společníka a ona k tobě opravdu přijede: objeví se mimo dohled, přijde pěšky nebo přijede autem, napíše ti, až bude na místě, a počká na tebe.",
    ["Meet at my waypoint when I ask"] = "Přijít k mému bodu, když požádám",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Vypnuto: Pozvat přivede společníka hned k tobě.\n\nZapnuto: společník, kterého pozveš tlačítkem Pozvat, na kartě Kontakty nebo zprávou, k tobě dojde a přijde po čase, který tady nastavíš. Až bude na místě, napíše ti, počká, a když nepřijdeš, odejde naštvaný (a bude si to pamatovat).",
    ["Right now"] = "Hned teď",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Hned teď: vyrazí, jakmile bude připravená.\n\nZa 2, 5 nebo 10 minut: skutečné minuty hraní, takže přijede v ten čas. Pak čeká stejně dlouho jako to zpoždění.",
    ["She texts you"] = "Posílat ti zprávy",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Napíše ti, když přijede, když zrušíš a když to vzdá. Vypnuto: žádné zprávy (i tak si pamatuje, že ji necháš čekat).",
    ["Something came up and I can't make it. Sorry."] = "Něco mi vyskočilo a nestihnu to. Promiň.",
    ["Walk"] = "Pěšky",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Pěšky: objeví se mimo tvůj dohled a dojde k tobě pěšky.\n\nAutem: když je poblíž silnice, přijede, zastaví na silnici, vystoupí a zbytek půjde pěšky. Bez silnice jde pěšky. Auto zůstane poblíž na jízdu a zmizí, když opustí tvoji skupinu nebo když se oba vzdálíte od auta.",
    ["When she arrives"] = "Až přijede",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Když ji požádáš, ať přijde k tvému bodu, a na mapě je nastavená značka, jde tam a řekne to. Vypnuto: vždy přijde tam, kde jsi.",
    ["Your position cannot be read yet."] = "Tvou polohu zatím nelze zjistit.",
    ["on her way"] = "na cestě",
    ["the meeting spot"] = "místo setkání",
    ["waiting at {place}"] = "čeká na {place}",
    ["{name} is already on the way."] = "{name} už je na cestě.",
    ["{name} is on her way."] = "{name} je na cestě.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} je na cestě. Asi {minutes} minut.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Ráda tě vidím. Jdeme.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Nechat se odstěhovat",
    ["That companion is not available."] = "Tenhle společník není k dispozici.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Ten byt nemáš.",
    ["at home"] = "doma",
    ["out"] = "venku",
    ["with you"] = "s tebou",
    ["{count} more housemates"] = "{count} dalších spolubydlících",
    ["{name} has moved out."] = "{name} už u tebe nebydlí.",
    ["{name} is back at home."] = "{name} je zpátky doma.",
    ["{name} joins you."] = "{name} se k tobě přidává.",
    ["{name} moves into {apartment}."] = "{name} se stěhuje do {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} nově bydlí v {apartment} a zůstává ve tvé skupině, dokud nepůjde domů.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} už u tebe nebydlí. Jinak zůstává beze změny.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · bydlí v {apartment} · {state}",
    ["Companions change outfits"] = "Společníci mění oblečení",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Společníci tvé skupiny se čas od času převlékají: jiný vzhled za dne a jiný v noci, a domácí oblečení doma, pokud ho postava má.\n\nJen mimo tvůj dohled, nikdy přímo před tebou, a jen u vlastních kopií tvé skupiny, nikdy u postav ze hry. Když to vypneš, zůstanou v tom, co mají oblečené právě teď.",
    ["Choose how often companions speak up."] = "Vyber, jak často se společníci ozvou.",
    ["Companions speak up"] = "Společníci se ozvou",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Jak na tom V je podle jiných modů, pokud jsou nainstalované: například únava, hlad, žízeň, nervy a závislosti z Dark Future. Také to, co má V viditelně na sobě, když je zapnutý outfit z Equipment-EX, aby postavy popisovaly outfit, a ne oblečení, které skrývá.\n\nVe výchozím nastavení vypnuto. Vypnuto: nic se neposílá a z těchto modů se nic nečte.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Jak dlouho uplynulo od posledního rozhovoru V s touto postavou, ve hře i ve skutečných dnech: od včerejšího večera, nebo dny zpátky. Říká se jen tehdy, když je mezera dost dlouhá, aby na tom záleželo, a ve stejném rozhovoru už znovu ne.\n\nVypnuto: nic se neposílá a mod kvůli tomu přestane číst herní čas.",
    ["Music and TV"] = "Hudba a TV",
    ["Other mods’ state"] = "Stav ostatních modů",
    ["Speaks up normally"] = "Mluví běžně",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Píseň hrající v autorádiu, když V jede s postavou, nebo v kapesním rádiu V, a to, co běží v televizi poblíž V.\n\nVypnuto: nic se neposílá a mod to z hry nečte.",
    ["Time since last talk"] = "Čas od posledního rozhovoru",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Společníci ve družině se občas sami ozvou: v klidné chvíli nebo po scéně. Když jsou poblíž dva nebo více, často vznikne krátký rozhovor mezi nejvýše třemi z nich, do kterého se lze zapojit mluvením. Nikdy během bojů, scén, hovorů nebo v menu.\n\nZřídka: asi 2 za hodinu hraní. Běžně: asi 4. Často (výchozí): asi 6.\n\nKdyž se ozve i Johnny, obě četnosti se sečtou a střídají se.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand reaguje na klávesy „Mluvit s Johnnym“ jako hlas v hlavě V, jakmile ho tam příběh zavede. Přiřaďte klávesu položce „Mluvit s Johnnym“ na stránce Klávesy: výchozí stav je žádná.\n\nZapnuto: odpoví, když na něj promluvíte. Zřídka: ozve se sám, asi 2 za hodinu. Běžně: asi 4. Často: asi 6.\n\nKdyž se ozývají i společníci, sazby se sečtou a střídají se.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Vyber, které živé herní informace se postavám předají, například poloha, čas, počasí, společníci, zdraví, peníze, výbava, úkoly, hudba a TV a stav ostatních modů.\n\nVe výchozím nastavení je vše zapnuto kromě stavu jiných modů, který je vypnutý. Vypnutý druh se nepošle žádnému poskytovateli konverzace.",
    ["Housemates"] = "Spolubydlící",
    ["Housemates talk to each other"] = "Spolubydlící spolu mluví",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Když jsou dva nebo více spolubydlících doma s tebou, čas od času spolu promluví.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Postavy, kterým řekneš, že mohou zůstat u tebe, se nastěhují do tvých bytů a bydlí tam.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Postavy, kterým řekneš, že mohou zůstat u tebe, se nastěhují do tvých bytů a bydlí tam.\n\nVe výchozím stavu vypnuto.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Zapnuto: postavy, kterým řekneš, že mohou zůstat u tebe, se nastěhují do tvých bytů a bydlí tam, a můžeš je vzít s sebou.\n\nVypnuto: nic z toho neběží. Po vypnutí se z tvých bytů odstěhují, ale zapamatuje se, kdo tam bydlel, takže po zapnutí se vrátí.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "kód OmniVoice se v něm nepovedlo načíst",
    ["PyTorch is not installed in it"] = "PyTorch není v něm nainstalován",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Tvůj vlastní Python (omni-python.txt) se testuje. Otevři tuto stránku za chvíli znovu.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Tvůj vlastní Python (omni-python.txt) se testuje, když se OmniVoice spustí nebo když se tato stránka znovu zkontroluje.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Tvůj vlastní Python (omni-python.txt) spouští OmniVoice s {backend} na {card}. Experimentální.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Tvůj vlastní Python (omni-python.txt) se nepoužíval: {reason}. OmniVoice používá Python z Runtime, který vyžaduje kartu NVIDIA.",
    ["a test on the graphics card failed"] = "test na grafické kartě selhal",
    ["it did not start or did not answer in time"] = "nespustil se nebo neodpověděl včas",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "jeho PyTorch nenašel grafickou kartu (bez CUDA nebo ROCm)",
    ["the OmniVoice pack is not installed"] = "balík OmniVoice není nainstalován",
    ["the file does not name a python.exe that exists"] = "soubor neuvádí existující python.exe",
    ["the module {module} is missing in it"] = "modul {module} v něm chybí",
    ["1 minute"] = "1 minuta",
    ["2 people"] = "2 osoby",
    ["3 people"] = "3 osoby",
    ["4 people"] = "4 osoby",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Všechny postavy, které u tebe bydlí, se stěhují jednoho času, ze všech bytů. Členové skupiny, kteří tam nebydlí, nejsou dotčeni. Spolubydlící, který je s tebou, zůstane v tvé skupině.",
    ["Evict"] = "Nechat se odstěhovat",
    ["Evict all housemates"] = "Nechat se odstěhovat všechny spolubydlící",
    ["Housemates in one chat"] = "Spolubydlící v jednom chatu",
    ["Housemates moved out: {count}"] = "Spolubydlící se odstěhovali: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Jak dlouho zůstávají spolubydlící po chatu potichu, než mohou začít další. Nastavení Společníci se ozvou stále omezuje, kolik chatů přijde za hodinu.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Kolik spolubydlících se připojí k jednomu chatu, když je tolik lidí doma blízko sebe. Mluví jeden po druhém. S méně lidmi doma je chat tak velký, jak jen může být.",
    ["Move-in apartment"] = "Byt k nastěhování",
    ["Nobody lives at your place."] = "U tebe nikdo nebydlí.",
    ["Pause between chats"] = "Pauza mezi chaty",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Kde se postava nastěhuje, když řekneš, že může zůstat, ale nepojmenuješ byt a nestojíš v jednom ze svých.\n\nZeptej se mě: Ona se ptá, kterého. Jinak si vezme byt, který si zde vybereš. Jsou uvedeny jen byty, které vlastníš.",
    ["Ask me"] = "Zeptej se mě",
    ["Could not start"] = "Nepodařilo se spustit",
    ["Did not start"] = "Nespustilo se",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Pokud složka existuje, nejnovější log v red4ext/logs napoví, proč ji RED4ext nenačetl: antivir odstranil soubor, nebo chybí Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Nejdřív načti uloženou hru. Klávesu lze nastavit jen při načtené hře.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Mod žádný stisk klávesy nedostal, takže se nic nezměnilo. Pokud se klávesy z tohoto menu nedostanou, nastav klávesu v Cyber Engine Tweaks v části pro klávesy: funguje to stejně.",
    ["Runtime incomplete"] = "Runtime je neúplný",
    ["Runtime not loaded"] = "Runtime nenačten",
    ["Service not running ({reason})"] = "Služba neběží ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Plugin Runtime je načtený, ale konverzační služba v této relaci nezanechala žádnou stopu. launcher.log v red4ext/plugins/AiNpcCyberpunkCode napoví proč: launcher.ini vypnutý, chybějící Node nebo Node blokovaný bezpečnostním programem. Oprav to a restartuj hru.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Konverzační služba nevidí složku tohoto modu ve hře: virtuální složky správce modů nebo složku, kterou nesmí číst. Rozbal Runtime přímo do složky Cyberpunk 2077, nebo spusť hru ze správce modů, který Runtime obsahuje.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Konverzační služba se spustila, ale nikdy se neohlásila. Bezpečnostní program ji pravděpodobně hned zastavil, nebo Node na tomto PC nejde spustit. Povol red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe v bezpečnostním programu a potom restartuj hru.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows nedovolil hře spustit konverzační službu (chyba {error}). Bezpečnostní program může blokovat node.exe v red4ext/plugins/AiNpcCyberpunkMod/app/node: povol ho a potom restartuj hru.",
    ["Add a server address first."] = "Nejprve přidejte adresu serveru.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Serveru třikrát položí otázku, kdo je, a zobrazí, zda je dostupný, jak dlouho odpovídá a jakou má verzi. Žádnou řeč neposílá.",
    ["Connected. The server speaks with {voice}."] = "Připojeno. Server mluví hlasem {voice}.",
    ["Custom voices"] = "Vlastní hlasy",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Smaže uloženou adresu serveru. Vzdálený OmniVoice ji potřebuje, aby mohl mluvit.",
    ["It answers in {ms} ms."] = "Odpovídá za {ms} ms.",
    ["Its voice runs on {device}."] = "Jeho hlas běží na {device}.",
    ["Loading"] = "Načítání",
    ["Not connected. Replies show as text until the server answers."] = "Nepřipojeno. Odpovědi se zobrazují jako text, dokud server neodpoví.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Na této adrese nic neodpovědělo. Zkontrolujte, zda server běží, zda jsou správně adresa a port a zda jsou oba počítače ve stejné síti. Server spuštěný s výchozím nastavením naslouchá jen na svém počítači: spusťte ho s adresou pro naslouchání 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Vypnuto. OmniVoice běží na tomto počítači.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Zapnuto, ale není uložena žádná adresa serveru. OmniVoice zatím nemůže mluvit.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Zapnuto, ale není uložena žádná adresa serveru. Dokud ji nepřidáte, použije se Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Zapnuto, ale není uložena žádná adresa serveru. Server zatím nepoužívá.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Zapnuto, ale v položce Hlasy společníků je zvolen cloudový hlas, takže se server nepoužívá.",
    ["On. Waiting for the conversation service."] = "Zapnuto. Čeká se na konverzační službu.",
    ["Paste address"] = "Vložit adresu",
    ["Remote OmniVoice"] = "Vzdálený OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Vykresluje hlasy na jiném počítači nebo grafické kartě se serverem OmniVoice, aby si tento počítač zachoval snímky.\n\nZapněte, stiskněte Použít a níže přidejte adresu serveru. Server pak mluví za každou volbu Pocket nebo OmniVoice v položce Hlasy společníků; cloudový hlas zůstává, jak byl zvolen. Pokud nelze server dosáhnout, odpovědi se zobrazují jako text a mod to zkouší znovu každých pár sekund.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Vykresluje hlasy OmniVoice na jiném počítači nebo grafické kartě, na kterém běží server OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Vykresluje hlasy Pocket a OmniVoice na jiném počítači nebo grafické kartě: vypínač, adresu serveru a test připojení. Funguje, ať je výše zvolen kterýkoli z těchto hlasů.",
    ["Server address"] = "Adresa serveru",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Něco odpovědělo, ale není to server OmniVoice. Zkontrolujte port.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Spusťte server OmniVoice na druhém počítači. Jeho okno zobrazuje adresu, kterou použít, například 192.168.1.20:8765. Zkopírujte ji a pak zvolte Vložit adresu. Načte se ze schránky jednou a uloží se na tomto počítači.\n\nNa stejném počítači použijte 127.0.0.1:8765. Můžete také zapsat address=192.168.1.20:8765 do souboru player-remote-omnivoice.txt ve složce konverzační služby.\n\nNic se mu neposílá, dokud není zapnut Vzdálený OmniVoice a zvolen OmniVoice, nebo dokud nestisknete Ověřit.",
    ["Status"] = "Stav",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Server OmniVoice nelze dosáhnout. Odpovědi se zobrazují jako text, dokud neodpoví. Mod se na něj ptá znovu každých pár sekund.",
    ["The clipboard does not hold a server address."] = "Schránka neobsahuje adresu serveru.",
    ["The clipboard is empty. Copy the address first."] = "Schránka je prázdná. Nejprve zkopírujte adresu.",
    ["The port must be a number from 1 to 65535."] = "Port musí být číslo od 1 do 65535.",
    ["The server address was removed."] = "Adresa serveru byla odebrána.",
    ["The server answered but could not load its voice. Its window says why."] = "Server odpověděl, ale nemohl načíst svůj hlas. Jeho okno uvádí důvod.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Server odpověděl, ale hlas se stále načítá. Zkuste to za minutu.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Server je jiná verze. Použijte složku serveru a mod ze stejného vydání.",
    ["The server is ready."] = "Server je připraven.",
    ["The server refused the request."] = "Server žádost odmítl.",
    ["The server took too long to answer."] = "Server odpovídal příliš dlouho.",
    ["Use the address only: no user name, no path, no #."] = "Uveďte jen adresu: bez uživatelského jména, bez cesty a bez #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Uveďte adresu, kterou zobrazuje okno serveru, například 192.168.1.20:8765, bez https://.",
    ["Waiting for the server to answer…"] = "Čeká se, až server odpoví…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Zda je server právě používán. Kontroluje se, když je potřeba hlas, a po chybě znovu každých pár sekund, nikdy během hraní.",
    ["Your own character, made in the character editor."] = "Tvoje vlastní postava, vytvořená v editoru postav.",
    ["Build for your game"] = "Sestavení pro tvou hru",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Tvoje hra je {game}, ale Runtime je pro hru {runtime}. Stáhni celý instalační zip pro hru {game} ze stránky modu na Nexus Mods (hlavní soubor je pro hru 2.5, volitelný soubor pro hru 2.31), rozbal ho do složky Cyberpunk 2077 přes tu stávající a pak restartuj hru.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Tvoje hra je {game}, ale Scripts jsou pro hru {scripts}. Stáhni aktualizační zip pro hru {game} ze stránky modu na Nexus Mods (aktualizační soubor je pro hru 2.5, volitelný aktualizační soubor pro hru 2.31), nainstaluj ho přes ty stávající a pak restartuj hru.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Tvoje hra je {game}, ale Scripts a Runtime jsou pro hru {scripts}. Stáhni celý instalační zip pro hru {game} ze stránky modu na Nexus Mods (hlavní soubor je pro hru 2.5, volitelný soubor pro hru 2.31), rozbal ho do složky Cyberpunk 2077 přes ty stávající a pak restartuj hru.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts jsou pro hru {scripts}, ale Runtime je pro hru {runtime}, a verze hry neodpovídá ani jednomu z nich. Rozbal celý instalační zip vytvořený pro stejnou hru jako tvoje (z Nexus Mods) do složky Cyberpunk 2077 a pak restartuj hru.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime je pro hru {other}, tvoje je {game}. Stáhni celý instalační zip pro {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts jsou pro hru {other}, tvoje je {game}. Stáhni aktualizační zip pro {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Mod je pro hru {other}, tvoje je {game}. Stáhni celý zip pro {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts pro hru {scripts}, Runtime pro {runtime}. Musí si odpovídat. Viz Nápověda.",
    ["Choose one of the listed microphones."] = "Vyber jeden z uvedených mikrofonů.",
    ["Microphone"] = "Mikrofon",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Mikrofon, který jsi vybral v Nastavení ({chosen}), není připojen, proto se použije výchozí vstup Windows: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Mikrofon, který jsi vybral v Nastavení, není připojen, proto se použije výchozí vstup Windows.",
    ["Windows default"] = "Výchozí ve Windows",
    ["not connected"] = "není připojen",
    ["{name}, chosen in Settings > Voices."] = "{name}, vybráno v Nastavení > Hlasy.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, výchozí vstup Windows. Jiný lze vybrat v Nastavení > Hlasy > Mikrofon.",
    ["Gameplay"] = "Hratelnost",
    ["Revenge ambushes"] = "Pomstná přepadení",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted. The threats need Talk to ordinary NPCs."] = "Gang, který pořád zabíjíš, ti vzácně pošle malou skupinu s krátkou výhrůžkou k vykřiknutí. Po každé následuje dlouhé čekání.\n\nNikdy během boje, scény, hovoru, ve vozidle, uvnitř, v bezpečné zóně nebo když tě hledá policie. Výhrůžky vyžadují „Mluvit s běžnými NPC“.",
    ["Speak dialogue choices"] = "Říkat volby v dialogu",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Řekni volbu v dialogu, aby se vybrala: její slova, část z nich nebo její číslo (\"dvě\", \"poslední\"). Pokud nic jasně nesedí, nic se nevybere. Žádná postava neodpoví.\n\nStiskne šipky a Enter, takže hra musí být v popředí. Vyžaduje rozpoznávání řeči na tomto počítači. Nejlépe fungují sluchátka.",
    ["No option matched. Say its number."] = "Žádná možnost neodpovídá. Řekni její číslo.",
    ["Two options fit. Say its number."] = "Hodí se dvě možnosti. Řekni její číslo.",
    ["Speaking a choice needs speech recognition on this PC."] = "Vyslovení volby vyžaduje rozpoznávání řeči na tomto počítači.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "ROCm PyTorch od AMD tuto kartu zatím nepodporuje.",
    ["Another setup is already running. Wait for it to finish."] = "Jiná instalace už běží. Počkej, až skončí.",
    ["Cancelled"] = "Zrušeno",
    ["Cancelling…"] = "Ruším…",
    ["Checking your card…"] = "Kontroluji tvou kartu…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Stahuji {done} z {total} MB ({percent}%)",
    ["Downloading…"] = "Stahuji…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Experimentální. Pocket mluví, dokud OmniVoice není připraven. Místní hlas se nikdy nepřepne na cloudový hlas.",
    ["Frees about {disk} GB."] = "Uvolní asi {disk} GB.",
    ["Frees the space it took."] = "Uvolní místo, které zabrala.",
    ["Install"] = "Nainstalovat",
    ["Installed"] = "Nainstalováno",
    ["Installed. OmniVoice uses it when it starts."] = "Nainstalováno. OmniVoice ji použije, až se spustí.",
    ["It is kept in the mod’s data folder on drive C:."] = "Je uložena ve složce dat modu na disku C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Běží na pozadí, zatímco hraješ. Hra běží dál a nic jiného se nemění.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Zabere asi {disk} GB na disku C: ve složce dat modu.",
    ["MIOpen convolutions (AMD)"] = "Konvoluce MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Na tomto PC není k dispozici. Potřebuje kartu AMD Radeon a balíček OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice pro AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice na AMD: nejdřív nastav",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "OmniVoice se pak na této kartě nespustí, dokud ho znovu nenastavíš.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Zapnuto: MIOpen od AMD počítá konvoluce, s MIOPEN_FIND_MODE=2 a MIOPEN_FIND_ENFORCE=1. Vypnuto: vlastní konvoluce PyTorch. Které je rychlejší, závisí na kartě a ovladači: pokud jsou hlasy pomalé nebo se zastaví uprostřed, zkus druhou možnost. Jen pro karty AMD. OmniVoice se s novou volbou restartuje, když je nečinný.",
    ["Own Python"] = "Vlastní Python",
    ["Ready"] = "Připraveno",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Připraveno. OmniVoice běží na {card} přes ROCm od AMD.",
    ["Reinstall"] = "Znovu nainstalovat",
    ["Remove AMD setup"] = "Odebrat instalaci AMD",
    ["Removing the AMD setup…"] = "Odebírám instalaci AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Spusť OmniVoice na své kartě AMD Radeon přes ROCm od AMD: jedno stažení, nastav ji odsud.",
    ["Set up OmniVoice for AMD"] = "Nastavit OmniVoice pro AMD",
    ["Starting the AMD setup…"] = "Spouštím instalaci AMD…",
    ["Testing it on your card…"] = "Zkouším ji na tvé kartě…",
    ["The AMD setup was removed."] = "Instalace AMD byla odebrána.",
    ["The OmniVoice pack is not installed. Install it first."] = "Balíček OmniVoice není nainstalován. Nejdřív ho nainstaluj.",
    ["The conversation service is not running. Restart the game."] = "Služba konverzací neběží. Restartuj hru.",
    ["The download did not finish. Check your connection and try again."] = "Stahování se nedokončilo. Zkontroluj připojení a zkus to znovu.",
    ["The download is not ready yet in this version of the mod."] = "Stahování zatím není v této verzi modu k dispozici.",
    ["The downloaded files did not check out. Try again."] = "Stažené soubory neprošly kontrolou. Zkus to znovu.",
    ["The files could not be unpacked. Try again."] = "Soubory se nepodařilo rozbalit. Zkus to znovu.",
    ["The setup did not finish. Try again."] = "Instalace se nedokončila. Zkus to znovu.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "Instalace neprošla testem na tvé kartě, takže ji OmniVoice nemůže použít.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "Instalace je nainstalovaná, ale neprošla testem na tvé kartě. Vyber Znovu nainstalovat.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "Na disku C: není dost volného místa. Uvolni nějaké a zkus to znovu.",
    ["This PC has no AMD Radeon card this setup can use."] = "Tohle PC nemá kartu AMD Radeon, kterou by tato instalace mohla použít.",
    ["Unpacking…"] = "Rozbaluji…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Místo toho se použije tvůj vlastní Python (omni-python.txt). Pro použití této instalace ten soubor smaž.",
    ["your AMD card"] = "tvoje karta AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: nejdřív nastav",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "Nastavení pro AMD (Nastavení > Hlasy > OmniVoice pro AMD) spouští OmniVoice s ROCm na {card}. Experimentální.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "Nastavení pro AMD nebylo použito: {reason}. Zvol Znovu nainstalovat v Nastavení > Hlasy > OmniVoice pro AMD. Do té doby mluví Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Mluvením si od svých postav půjčuj eddies, půjčuj jim eddies a vracejte si je. Každá postava má vlastní peníze podle svého příběhu a rozhoduje se podle toho, jak k tobě cítí. Občas tě o půjčku požádají.\n\nEddies přecházejí, jakmile postava souhlasí, a jen s tvými vlastními postavami (parta, pozvaní hosté, spolubydlící). Herní postavy o tom jen mluví. Ve výchozím stavu vypnuto.",
    ["Eddies with characters"] = "Eddies s postavami",
    ["The eddies could not be moved."] = "Eddies se nepodařilo přesunout.",
    ["You do not have enough eddies for that."] = "Na to nemáš dost eddies.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} už s tebou není, takže se žádné eddies nepřesunuly.",
    ["Add to favorites"] = "Přidat do oblíbených",
    ["One download of about {size} GB."] = "Jeden soubor o velikosti asi {size} GB.",
    ["One download."] = "Jedno stažení.",
    ["Remove from favorites"] = "Odebrat z oblíbených",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Nastav OmniVoice na své kartě AMD Radeon jedním stažením a vyber, jak bude běžet.",
    ["That entry cannot be a favorite."] = "Tuto položku nelze přidat mezi oblíbené.",
    ["You have too many favorites. Remove one first."] = "Máš příliš mnoho oblíbených. Nejdřív jednu odeber.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Tvoje karta AMD Radeon ({card}) může spustit OmniVoice. Nastav ho v Nastavení > Hlasy > OmniVoice pro AMD: jedno stažení, pak se spustí samo.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "Tvoje karta AMD Radeon může spustit OmniVoice. Nastav ho v Nastavení > Hlasy > OmniVoice pro AMD: jedno stažení, pak se spustí samo. Dokud to neuděláš, mluví Pocket.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Oblíbené se nepodařilo uložit, takže vydrží jen do zavření hry.",
    ["{count} matching characters"] = "Odpovídajících postav: {count}",
    ["{name} is no longer a favorite."] = "{name} už není mezi oblíbenými.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Uložená skupina pojme {count} postav, zbytek byl vynechán.",
    ["Already with you: {names}."] = "Už jsou s tebou: {names}.",
    ["Another saved party already has that name."] = "Jiná uložená skupina už tento název má.",
    ["Could not invite: {names}."] = "Nepodařilo se pozvat: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Smaže tuto uloženou skupinu. Postavy, které jsou teď ve tvé skupině, zůstanou nedotčené.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Pozve postavy této skupiny k tobě: {names}.\n\nDo tvé skupiny se přidají, nikoho nepropustí. Postava, která už je s tebou, se nepozve dvakrát. Každý, kdo nemůže přijít, bude jmenován i s důvodem.",
    ["Parties"] = "Skupiny",
    ["Party"] = "Skupina",
    ["Press Delete again to delete {name}."] = "Stiskni znovu Smazat a smaž {name}.",
    ["Press again"] = "Stiskni znovu",
    ["Press again to delete this saved party. Anything else cancels."] = "Stiskni znovu pro smazání této uložené skupiny. Cokoli jiného zruší.",
    ["Rename"] = "Přejmenovat",
    ["Rename party"] = "Přejmenovat skupinu",
    ["Renamed to {name}."] = "Přejmenováno na {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Nahradí postavy této uložené skupiny postavami, které jsou teď ve tvé skupině.",
    ["Save current party"] = "Uložit aktuální skupinu",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Uloženo jako {name}. Pod tím stiskni Pozvat skupinu, pozveš je znovu.",
    ["Saved party: {name}"] = "Uložená skupina: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Uloží postavy, které jsou teď ve tvé skupině, včetně kopií a tvých vlastních postav, jako skupinu, kterou můžeš pozvat znovu jedním stisknutím. Pojmenuje se Skupina 1, Skupina 2 a tak dál a objeví se níže.\n\nMůžeš mít až {count} uložených skupin.",
    ["Spawn"] = "Pozvat",
    ["Spawn party"] = "Pozvat skupinu",
    ["That party no longer exists."] = "Ta skupina už neexistuje.",
    ["The characters of this party: {names}."] = "Postavy této skupiny: {names}.",
    ["The party could not be saved."] = "Skupinu nebylo možné uložit.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Toto menu nemá textové pole, takže skupina si ponechá svůj název. Mod Configuration Menu ho má: napiš název do jeho hledacího pole.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Napiš nový název do hledacího pole nahoře (Mod Configuration Menu) a potom stiskni Přejmenovat. Native Settings UI nemá textové pole, takže skupina si tam ponechá název.",
    ["Type the new name in the Search box first, then press Rename."] = "Nejdřív napiš nový název do hledacího pole a potom stiskni Přejmenovat.",
    ["Update"] = "Aktualizovat",
    ["Update with current party"] = "Aktualizovat podle aktuální skupiny",
    ["You can keep {count} saved parties. Delete one first."] = "Můžeš mít {count} uložených skupin. Nejdřív jednu smaž.",
    ["Your party is empty. Invite someone first."] = "Tvoje skupina je prázdná. Nejdřív někoho pozvi.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Uložené skupiny se nepodařilo zapsat na disk, takže vydrží jen do zavření hry.",
    ["that character model is unavailable"] = "model postavy není k dispozici",
    ["the invitation was refused"] = "pozvání bylo odmítnuto",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "Smazáno: {name}.",
    ["{name} has nobody to invite."] = "{name} nemá koho pozvat.",
    ["{name} now has the characters of your party."] = "{name} má teď postavy z tvé skupiny.",
    ["{party}: inviting {names}."] = "{party}: pozývá {names}.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Přidá {name} mezi oblíbené. Jsou uvedeny nahoře na straně 1 a jako první na kartě Chat v telefonu. Aktualizace je nikdy nemění.",
    ["Favorites"] = "Oblíbené",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Zde je uvedeno jen prvních {count} oblíbených. Ostatní jsou v seznamu níže.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Strana {page} z {pages}: {kind} {first} až {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Stisknutím přejdete na stranu {page} z {pages}: {kind} {first} až {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Odebere {name} z oblíbených. Místo v seznamu níže zůstane zachováno.",
    ["This is the first page."] = "Toto je první strana.",
    ["This is the last page."] = "Toto je poslední strana.",
    ["characters"] = "postavy",
    ["entries"] = "položky",
    ["models"] = "modely",
    ["{count} more favorites"] = "Ještě {count} oblíbených",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} je nyní mezi oblíbenými. Oblíbené jsou nahoře na straně 1.",
    ["Favorite"] = "Oblíbené",
    -- Look and moves part of the character editor (docs/CHARACTER_EDITOR.md)
    ["That look is not one of this character’s."] = "Tento vzhled nepatří této postavě.",
    ["That choice is not available."] = "Tato volba není k dispozici.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "Editor uchovává volby pro {max} postav. Nejdřív některou obnovte.",
    ["Usual look"] = "Obvyklý vzhled",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "Domácí oblečení: tílko, boxerky, žabky",
    ["No jacket"] = "Bez bundy",
    ["No jacket and harness"] = "Bez bundy a s popruhy",
    ["Home clothes: shirt and trousers"] = "Domácí oblečení: košile a kalhoty",
    ["Home clothes: tank top and trousers"] = "Domácí oblečení: tílko a kalhoty",
    ["Hooded jacket"] = "Bunda s kapucí",
    ["Home clothes: t-shirt and trousers"] = "Domácí oblečení: tričko a kalhoty",
    ["Collar down"] = "Límec rozložený",
    ["Valentino look"] = "Vzhled Valentino",
    ["Suit"] = "Oblek",
    ["Club night, no jacket"] = "Noční klub, bez bundy",
    ["Solo look"] = "Vzhled Solo",
    ["Date night"] = "Večer pro dva",
    ["T-shirt"] = "Tričko",
    ["Vest"] = "Vesta",
    ["Paradise look"] = "Vzhled Paradise",
    ["Bartender"] = "Barman",
    ["Dress without the fur coat"] = "Šaty bez kožichu",
    ["Trench coat"] = "Trenčkot",
    ["Without the coat"] = "Bez kabátu",
    ["CEO look with coat"] = "Vzhled CEO s kabátem",
    ["CEO look"] = "Vzhled CEO",
    ["Pyjamas"] = "Pyžamo",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "Vrátit se k obvyklému vzhledu a pohybům pro {name}? Vaše volby v této části budou odstraněny.",
    ["Back to the usual look and moves."] = "Zpět k obvyklému vzhledu a pohybům.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "Volby pro to, jak tato postava vypadá a jak se pohybuje. Fungují se všemi možnostmi konverzace, včetně Convai, kromě délky odpovědi.",
    ["Outfit"] = "Oblečení",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "Automaticky sleduje nastavení hry „Společníci mění oblečení“: denní a noční vzhledy, občas změnu a domácí oblečení doma. Vzhled, který vyberete, se nosí pořád. Oblečení mění jen vaši vlastní společníci a obyvatelé, a to, když se nikdo nedívá. Postavy, které hra umísťuje, se nikdy nemění.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "Tato postava má ve hře jen jeden vzhled, takže není z čeho vybírat oblečení.",
    ["Talking gestures"] = "Gesta při mluvení",
    ["How the hands move while they speak a longer reply."] = "Jak se pohybují ruce, když mluví delší odpověď.",
    ["Normal"] = "Normální",
    ["Calm: smaller gestures, not as often"] = "Klidná: menší gesta, ne tak často",
    ["Lively: bigger gestures, more often"] = "Živá: větší gesta, častěji",
    ["None: the hands stay at rest"] = "Žádná: ruce zůstávají v klidu",
    ["Nod while you talk to them"] = "Přikyvovat, když s nimi mluvíte",
    ["A small nod now and then while you speak."] = "Občas malé přikyvování, když mluvíte.",
    ["Idle moves"] = "Pohyby v klidu",
    ["What they do now and then while they stand beside you."] = "Co dělají občas, když stojí vedle vás.",
    ["Plain stances only, no props like a cup or a cigarette"] = "Jen obyčejné postoje, bez rekvizit jako šálek nebo cigareta",
    ["None: they keep the stance they have"] = "Žádné: zůstávají ve svém postoji",
    ["Sit down and take a place"] = "Posadit se a zaujmout místo",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "Když si sednete, usedne vedle vás a ve vašem bytě doma zaujme místo na sedadle nebo na určeném místě. Když je to vypnuto, stojí vedle vás.",
    ["Comment on fights and loot"] = "Komentovat boje a kořist",
    ["Switched off, they say nothing about fights or about what you pick up."] = "Když je to vypnuto, nic neříkají o bojích ani o věcech, které seberete.",
    ["Reply length"] = "Délka odpovědi",
    ["Shorter: up to about {words} words"] = "Kratší: až zhruba {words} slov",
    ["Very short: up to about {words} words"] = "Velmi krátká: až zhruba {words} slov",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "Uložená volba se projeví do několika sekund. Oblečení se mění, když se nikdo nedívá.",
    ["Look and moves"] = "Vzhled a pohyby",
    ["Shift"] = "Shift",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "Podrž Shift, Ctrl nebo Alt při stisku klávesy a nastavíš kombinaci, například Shift+F5. Kombinace se spustí jen tehdy, když jsou drženy přesně tyto klávesy, a obyčejná klávesa se nespustí, dokud je některá z nich držena. Ve hře Shift znamená sprint, Ctrl úhyb a Alt otevírá kolo zbraní, takže to udělá i V.",
    ["Disk space"] = "Místo na disku",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "Tvůj disk {drive} je skoro plný ({free} GB volných). Uvolni místo, aby mod mohl uložit logy a vzpomínky.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "Vstup označený (!) vypadá jako smyčkový nebo virtuální vstup, například Stereo Mix, CABLE Output nebo výstup mixéru. Může přenášet zvuk jiných aplikací, například druhé strany hovoru, proto mod nikdy takový vstup nevybere sám.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "Vybraný vstup vypadá tak, že přenáší zvuk počítače, nejen tvůj hlas. Pokud postavy slyší tvoje hovory, vyber svůj skutečný mikrofon.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} vypadá tak, že přenáší zvuk počítače, například hovor, nejen tvůj hlas. Vyber svůj skutečný mikrofon v Nastavení > Hlasy > Mikrofon.",
    ["Companions can see"] = "Společníci vidí",
    ["Each line also gets a recent picture of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model that can see. A model that cannot just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "Každý řádek dostane i čerstvý obraz okolí z okna hry. Funguje s každým poskytovatelem konverzace. Local AI potřebuje model, který umí vidět. Model, který nemůže, dostane jen tvoje slova.\n\nPouze okno hry, pouze když je někdo poblíž, krátce uložené v paměti. Vypnuto znamená, že se nic nezachytává.",
    ["The yellow border is Windows showing a capture. Turn off Companions can see to stop it."] = "Žlutý rámeček je Windows, který ukazuje záznam. Zastav ho vypnutím volby Společníci vidí.",
    ["This Local AI model cannot see pictures, so replies use only your words."] = "Tento model Local AI neumí vidět obrázky, odpovědi tedy berou jen tvá slova.",
    ["This model can see pictures with its vision file, from {folder}/vision on Hugging Face."] = "S vision souborem z {folder}/vision na Hugging Face tento model uvidí obrázky.",
    ["Your Custom endpoint does not accept pictures, so replies use only your words."] = "Tvůj Custom koncový bod nepřijímá obrázky, odpovědi tedy berou jen tvá slova.",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "Zatím není uložen žádný klíč API. Zkopíruj klíč od poskytovatele, stiskni Vložit klíč API a pak to otestuj znovu.",
    ["Add"] = "Přidat",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "Odstraní toto bezplatné nastavení: URL endpointu, ID modelu a s ním uložený klíč.",
    ["Allow Local AI to use RAM"] = "Povolit Local AI používat RAM",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "Vypnuto: když zvolený model Local AI nevejde do volné grafické paměti vedle hry, místo něj se načte menší model, který se vejde, a zobrazí se jedno upozornění.\n\nZapnuto: zvolený model se ponechá a jeho část běží z systémové paměti (RAM) na procesoru. Odpovědi budou pomalejší a dostaneš o tom jedno upozornění. Potřebuje dost volné RAM a hra může mít na procesor méně času.",
    ["Using {model}"] = "Používá {model}",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "{model} se používá, protože zvolený model se vedle hry nevešel. Tvoje volba se nemění.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "Local AI ponechává {model} podle tvého povolení, část je v systémové paměti. Odpovědi budou pomalejší.",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Výběr Convai nebo Google Gemini tuto volbu vypne. Voxtral se s ní nepoužívá: hlas Voxtral se přepne na Pocket a po vypnutí se vrátí.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Convai se nepodařilo přihlásit. Zkus to za chvíli, nebo v Nastavení > Poskytovatel konverzací vyber Google Gemini nebo Local AI.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Google Gemini, Local AI or Custom as the conversation provider in the settings."] = "Convai právě odpovídá, takže tyto změny zatím nemají účinek. V nastavení vyber jako poskytovatele konverzací Google Gemini, Local AI nebo Vlastní.",
    ["Convai: Google Gemini has no key yet"] = "Convai: Google Gemini zatím nemá klíč",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "Nejdřív zkopíruj svůj klíč API Mistral a pak stiskni Add. Vyplní URL endpointu a ID modelu pro Mistral (Ministral 8B) a uloží tvůj klíč ze schránky. Stejný klíč pohání cloudový hlas Voxtral.\n\nNovým účtům Mistral už možná nebude přidělen bezplatný klíč API.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 1,000 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "Nejdřív zkopíruj svůj klíč z Google AI Studio (aistudio.google.com/apikey, stačí účet Google, karta není potřeba). Přečte se ze schránky jednou a uloží se na tomto počítači.\n\nBezplatný tarif má denní limit přibližně 1 000 odpovědí, není nabízen v každé zemi a Google může chaty z bezplatného tarifu používat ke zlepšování svých produktů.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Uprav v prohlížeči životopis, styl mluvení, pravidla mluvení a vzpomínky postavy a prompty pro jednotlivé možnosti AI, nebo vytvoř vlastní postavu.\n\nFunguje s Google Gemini, Local AI a Vlastní, ne s Convai. Změny se projeví od příští odpovědi.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Uprav v prohlížeči životopisy, pravidla a vzpomínky postav a prompty pro jednotlivé možnosti AI.\n\nFunguje s Google Gemini, Local AI a Vlastní, ne s Convai. Změny se projeví od příští odpovědi.",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Z Convai nebo Google Gemini ho zapnutí vybere Local AI, nebo Vlastní, pokud Local AI není nainstalována. S Local AI vybere také největší necenzurovaný model, který se vejde. Vypnutí obnoví tvé dřívější volby.",
    ["Google Gemini (free plan)"] = "Google Gemini (zdarma)",
    ["Google Gemini API key"] = "Klíč API Google Gemini",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Google Gemini zatím nemá klíč, takže se používá Convai. Přidej svůj klíč v Nastavení > Poskytovatel konverzací.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "Odpovědi Google Gemini mluví místním hlasem, ne cloudovým hlasem Convai.",
    ["Google Gemini: key not accepted"] = "Google Gemini: klíč nebyl přijat",
    ["The service is not available in your region."] = "Služba ve tvém regionu není dostupná.",
    ["Google accepted the key."] = "Google klíč přijal.",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "Google tento klíč nepřijal. Zkontroluj ho v Google AI Studio, pak klikni na Odebrat a správný klíč přidej tlačítkem Přidat.",
    ["Google accepted the key, but the free allowance is used up for now."] = "Google klíč přijal, ale bezplatný limit je prozatím vyčerpán.",
    ["The key is saved, but Google Gemini is not available in your region."] = "Klíč je uložen, ale Google Gemini ve tvém regionu není dostupný.",
    ["The key is saved, but Google could not be reached to check it."] = "Klíč je uložen, ale Google nebylo možné kontaktovat k ověření.",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini: na minutu omezeno",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini: dnešní bezplatný limit vyčerpán",
    ["Google Gemini: not available in your region"] = "Google Gemini: ve tvém regionu nedostupný",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "Google nepřijal tvůj klíč Gemini. Zkontroluj ho v Google AI Studio a přidej znovu.",
    ["Your free Gemini allowance for today is used up. It resets at {time}. Use Convai or Local AI."] = "Tvůj dnešní bezplatný limit Gemini je vyčerpán. Obnoví se v {time}. Použij Convai nebo Local AI.",
    ["Your free Gemini allowance for today is used up. It resets tomorrow. Use Convai or Local AI."] = "Tvůj dnešní bezplatný limit Gemini je vyčerpán. Obnoví se zítra. Použij Convai nebo Local AI.",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "Google Gemini tě omezuje. Počkej minutu a zkus to znovu.",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini ve tvém regionu není dostupný. Použij Convai nebo Local AI.",
    ["Google Gemini is busy or had an error. Wait a minute, then try again."] = "Google Gemini je zaneprázdněn nebo nastala chyba. Počkej minutu a zkus to znovu.",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "Google Gemini nejde kontaktovat. Zkontroluj internet a zkus to znovu.",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "Model Gemini teď není dostupný. Zkus to později nebo použij Local AI.",
    ["Google Gemini: model unavailable"] = "Google Gemini: model není dostupný",
    ["Mistral (your key)"] = "Mistral (tvůj klíč)",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Vyžaduje klíč Mistral (přidej ho pomocí předvolby Mistral na stránce Custom endpoint)",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "Dosáhl jsi limitu konverzací. Zkus to později, nebo v Nastavení > Poskytovatel konverzací vyber Local AI nebo Google Gemini.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "Nejdelší odpověď ve slovech. Funguje s Google Gemini, Local AI a Custom, ne s Convai.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "Připojí se jako kopie modelu, ze kterého vznikla. Mluví přes Google Gemini, Local AI nebo Vlastní; s Convai mluví jako obyčejný člověk.",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Dnešní repliky Convai jsou pryč.\nObnoví se v {time}. Zkus Local AI (bez limitu) nebo Google Gemini (vlastní klíč).",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Dnešní repliky Convai jsou pryč.\nZkus Local AI (bez limitu) nebo Google Gemini (vlastní klíč).",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Dnešních {limit} replik Convai pryč.\nObnoví se v {time}. Zkus Local AI (bez limitu) nebo Google Gemini (vlastní klíč).",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Dnešních {limit} replik Convai pryč.\nZkus Local AI (bez limitu) nebo Google Gemini (vlastní klíč).",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Zapíná nebo vypíná obsahový balíček {name}. Balíček mění, jak postavy mluví. Jeho změny promptu fungují s Google Gemini, Local AI a Vlastní. U Convai platí jeho pravidla světa a jeho vlastní postavy Convai. Přepnutí se počítá od další odpovědi, nová jména po restartu.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "Co hra každé postavě říká o tomto okamžiku. Postava to zmíní jen tehdy, když se to hodí do rozhovoru.\n\nVypnutý druh se nepředává žádnému poskytovateli rozhovorů (Convai, Google Gemini, Local AI a Vlastní).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Kdo píše odpovědi tvých společníků. Změna čeká, dokud neběží žádná konverzace.\n\nBezplatný plán Convai nevyžaduje nastavení a dává lepší odpovědi. Klíč API Convai používá tvůj vlastní klíč. Google Gemini používá tvůj bezplatný klíč a jeho paměť zůstává na tomto počítači.\n\nS Google Gemini, Local AI nebo Vlastní je cloudový hlas Convai nahrazen místním hlasem. Řeč se rozpoznává na tomto počítači, takže hlasová klávesa funguje.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Kdo píše odpovědi tvých společníků. Změna čeká, dokud neběží žádná konverzace.\n\nBezplatný plán Convai nevyžaduje nastavení a dává lepší odpovědi. Klíč API Convai používá tvůj vlastní klíč. Google Gemini používá tvůj bezplatný klíč a jeho paměť zůstává na tomto počítači.\n\nS Google Gemini, Local AI nebo Vlastní je cloudový hlas Convai nahrazen místním hlasem. Rozpoznávání řeči pro hlasovou klávesu s nimi zatím není dostupné, takže piš zprávy ručně.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Dnešní limit {limit} replik jsi vyčerpal. Vrátí se v {time}. Chceš-li pokračovat hned, zvol Local AI (bez limitu) nebo Google Gemini (s vlastním klíčem).",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Dnešní limit {limit} replik jsi vyčerpal. Vrátí se zítra. Chceš-li pokračovat hned, zvol Local AI (bez limitu) nebo Google Gemini (s vlastním klíčem).",
    ["Your changes work with Google Gemini, Local AI and Custom. They do not apply to Convai."] = "Tvoje změny fungují s Google Gemini, Local AI a Vlastní. Na Convai se neuplatní.",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "Tvoje vlastní postavy mluví jen s Google Gemini, Local AI nebo Vlastní. S Convai mluví jako obyčejný člověk.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} je jedna z tvých vlastních postav. Potřebuje Google Gemini, Local AI nebo Vlastní, takže s Convai mluví jako obyčejný člověk.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} je jedna z tvých vlastních postav. Potřebuje Google Gemini, Local AI nebo Custom: vyber si jednoho v nastavení pod položkou „Poskytovatel konverzací“.",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "Tato postava potřebuje k odpovědi Google Gemini, Local AI nebo Vlastní.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Dosáhl jsi dnešního limitu Convai (bezplatný plán). Obnoví se v {time}. Chceš-li pokračovat hned, zvol jiného poskytovatele v Nastavení > Poskytovatel konverzací. Local AI je bez limitu a běží na tvém počítači. Google Gemini funguje s vlastním klíčem.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Dosáhl jsi dnešního limitu Convai (bezplatný plán). Zítra se obnoví. Chceš-li pokračovat hned, zvol jiného poskytovatele v Nastavení > Poskytovatel konverzací. Local AI je bez limitu a běží na tvém počítači. Google Gemini funguje s vlastním klíčem.",
    ["Add a key first"] = "Nejdřív přidej klíč",
    ["Add a key to choose it"] = "Pro výběr přidej klíč",
    ["Asks Inworld whether your saved key is accepted. It costs nothing and no speech is made."] = "Zeptá se Inworld, zda je uložený klíč přijat. Nic to nestojí a nevytváří se žádná řeč.",
    ["Chosen as the Companion voice"] = "Vybráno jako hlas společníka",
    ["Connected"] = "Připojeno",
    ["Deletes the saved key. If Inworld is your Companion voice, replies show as text until you add a key again."] = "Smaže uložený klíč. Pokud je Inworld hlasem tvých společníků, odpovědi se zobrazují jako text, dokud znovu nepřidáš klíč.",
    ["Inworld API key"] = "Klíč API Inworld",
    ["Inworld cloud voice"] = "Cloudový hlas Inworld",
    ["Inworld did not accept that key."] = "Inworld tento klíč nepřijal.",
    ["Inworld is not used with Mature content."] = "Inworld se s obsahem pro dospělé nepoužívá.",
    ["Inworld voice"] = "Hlas Inworld",
    ["Inworld · Cloud voice"] = "Inworld · Cloudový hlas",
    ["Inworld · needs key"] = "Inworld · chybí klíč",
    ["Inworld · not with Mature"] = "Inworld · bez obsahu 18+",
    ["Key refused"] = "Klíč odmítnut",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "Potřebuješ vlastní klíč Inworld z inworld.ai. Bezplatný plán Inworld je jednorázová zkouška asi na 70 minut řeči, poté platíš podle použití.\n\nNejdřív klíč zkopíruj a pak stiskni Přidat. Jednou se přečte ze schránky, Inworld ho ověří a uloží se na tomto počítači.",
    ["Not reachable"] = "Nedostupné",
    ["Not used with Mature content"] = "Nepoužívá se s obsahem pro dospělé",
    ["Ready to choose in Companion voices"] = "Připraveno k výběru v Hlasech společníků",
    ["Requires an Inworld key (add it in Settings > Voices > Custom voices)"] = "Vyžaduje klíč Inworld (přidej ho v Nastavení > Hlasy > Vlastní hlasy)",
    ["Speaks each companion in their own voice, on your own Inworld key. English only. Choose it under Companion voices, where it is listed last once a key is added."] = "Mluví každý společník vlastním hlasem přes tvůj klíč Inworld. Pouze angličtina. Vyber ho v Hlasech společníků, kde je po přidání klíče uveden jako poslední.",
    ["{voice} · needs Inworld key"] = "{voice} · vyžaduje klíč Inworld",
}
